js.text:

function grid$dmplvtc2(f){
  this.constructor(f);
}
grid$dmplvtc2.prototype = new DirEvent();
grid$dmplvtc2.prototype.afterInit = function(){
  var p = this._dir;
}

css.text:

.toolbar-close > div {
	background-position: -336px -400px !important;
.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
